'use strict';
function gcRememberRun(){const r=gc.run;if(r&&gcIsMS(r.method)){r.saved=true;return}if(!r||r.saved||gc.running||gc.paused||!(r.completed||r.stopped))return;gc.history.push({method:{...r.method},sample:r.components.map(c=>({id:c.id,concentration:c.concentration})),peaks:gcVisiblePeaks().map(p=>({...p})),acquired:gc.time,status:r.completed?'Complete':'Stopped'});gc.history=gc.history.slice(-8);r.saved=true;gcSave()}
function gcNextSamplePanel(){const disabled=!gc.run||!(gc.run.completed||gc.run.stopped)||gcLocked()||gseq.active;return `<button class="btn gc-next-bar" data-gc-next="prepare" ${disabled?'disabled':''}>Run another sample</button>`}
function gcPrepareNextSample(id){if(gcLocked()||gseq.active)return false;const vials=gcal.vials.filter(v=>v.exported),vial=vials.find(v=>v.id===Number(id));if(vials.length&&!vial){gcMessage('Choose a vial under Load prepared sample, then click Run another sample.');gcRender();return false}if(!gc.power||!gc.carrier){gcMessage('Power on and enable carrier gas before preparing the next injection.');gcRender();return false}const errors=gcValidation(gc.method);if(errors.length){gcMessage(errors.join(' '));gcRender();return false}const keepFlame=gc.flame;gcRememberRun();gc.preparingNext=true;if(vial)gcCalLoad(vial.id);if(gcIsMS()&&typeof gms!=='undefined')gms.autoEnable=true;gcEquilibrate({keepFlame});return true}
document.addEventListener('click',e=>{if(typeof page==='undefined'||page!=='instrumentation'||!e.target.closest('[data-gc-next="prepare"]'))return;gcPrepareNextSample(document.getElementById('gcPreparedSample')?.value||0)});
